package com.jobradar.taxonomy.location;import com.jobradar.common.api.*;import com.jobradar.common.pagination.PaginationParameters;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class LocationController{private final LocationService s;public LocationController(LocationService s){this.s=s;}@GetMapping("/api/v1/locations")public ApiResponse<PaginatedResponse<LocationDto>> list(@RequestParam(required=false)String search,@RequestParam(required=false)String keyword,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Locations retrieved successfully",s.browse(search==null?keyword:search,p,false));}@GetMapping("/api/v1/admin/locations")public ApiResponse<PaginatedResponse<LocationDto>> adminList(@RequestParam(required=false)String search,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Locations retrieved successfully",s.browse(search,p,true));}@PostMapping("/api/v1/admin/locations")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<LocationDto> create(@Valid @RequestBody LocationRequest r){return ApiResponse.success("Location created successfully",s.create(r));}@PutMapping("/api/v1/admin/locations/{id}")public ApiResponse<LocationDto> update(@PathVariable Integer id,@Valid @RequestBody LocationRequest r){return ApiResponse.success("Location updated successfully",s.update(id,r));}@PatchMapping("/api/v1/admin/locations/{id}/{state:activate|deactivate}")public ApiResponse<Void> active(@PathVariable Integer id,@PathVariable String state){s.active(id,state.equals("activate"));return ApiResponse.success("Location status updated successfully",null);}}
